1	package mcp
2	
3	import (
4		"context"
5		"fmt"
6		"os"
7		"time"
8	
9		"github.com/mark3labs/mcp-go/client"
10		"github.com/mark3labs/mcp-go/mcp"
11	)
12	
13	// StdioClient implements MCPClient for stdio transport
14	type StdioClient struct {
15		*BaseClient
16		mcpClient client.MCPClient
17	}
18	
19	// NewStdioClient creates a new stdio MCP client
20	func NewStdioClient(name string, config ClientConfig) *StdioClient {
21		baseClient := NewBaseClient(name, config)
22		return &StdioClient{
23			BaseClient: baseClient,
24		}
25	}
26	
27	// Connect establishes connection to the MCP server via stdio
28	func (c *StdioClient) Connect() error {
29		if c.connected {
30			return nil
31		}
32	
33		c.log(LoggingLevelInfo, "Connecting to MCP server with stdio transport")
34	
35		if c.config.Command == "" {
36			return fmt.Errorf("command is required for stdio transport")
37		}
38	
39		// Prepare environment variables
40		env := os.Environ()
41		for key, value := range c.config.Env {
42			env = append(env, fmt.Sprintf("%s=%s", key, value))
43		}
44	
45		c.log(LoggingLevelInfo, fmt.Sprintf("Starting MCP server: %s %v", c.config.Command, c.config.Args))
46		c.log(LoggingLevelDebug, fmt.Sprintf("Environment variables: %v", c.config.Env))
47	
48		// Create MCP client using the correct API
49		mcpClient, err := client.NewStdioMCPClient(c.config.Command, env, c.config.Args...)
50		if err != nil {
51			c.log(LoggingLevelError, fmt.Sprintf("Failed to create MCP client: %v", err))
52			return fmt.Errorf("failed to create stdio MCP client: %w", err)
53		}
54	
55		c.mcpClient = mcpClient
56	
57		// Initialize the connection with proper context handling
58		ctx := context.Background()
59		timeout := 30 * time.Second // default timeout
60		if c.config.Timeout > 0 {
61			timeout = c.config.Timeout
62		}
63	
64		ctx, cancel := context.WithTimeout(ctx, timeout)
65		defer cancel()
66	
67		// Use a channel to handle the initialization asynchronously
68		initDone := make(chan error, 1)
69	
70		go func() {
71			defer func() {
72				if r := recover(); r != nil {
73					c.log(LoggingLevelError, fmt.Sprintf("Panic during MCP initialization: %v", r))
74					initDone <- fmt.Errorf("panic during initialization: %v", r)
75				}
76			}()
77	
78			c.log(LoggingLevelDebug, "Starting MCP client...")
79			// Note: Connection starts automatically; Start() method is not required
80	
81			c.log(LoggingLevelDebug, "Initializing MCP client...")
82			// Initialize the client with a simple request (no params needed for basic initialization)
83			initResult, err := c.mcpClient.Initialize(ctx, mcp.InitializeRequest{})
84			if err != nil {
85				c.log(LoggingLevelError, fmt.Sprintf("Failed to initialize MCP client: %v", err))
86				initDone <- fmt.Errorf("failed to initialize MCP client: %w", err)
87				return
88			}
89	
90			c.log(LoggingLevelInfo, fmt.Sprintf("Initialized MCP client: %s v%s", initResult.ServerInfo.Name, initResult.ServerInfo.Version))
91			initDone <- nil
92		}()
93	
94		// Wait for initialization to complete or timeout
95		select {
96		case err := <-initDone:
97			if err != nil {
98				c.connected = false
99				return err
100			}
101			c.connected = true
102		case <-ctx.Done():
103			c.connected = false
104			return fmt.Errorf("timeout connecting to MCP server after %v", timeout)
105		}
106	
107		// Load available capabilities in background
108		go func() {
109			capCtx, capCancel := context.WithTimeout(context.Background(), timeout)
110			defer capCancel()
111	
112			if err := c.loadCapabilities(capCtx); err != nil {
113				c.log(LoggingLevelWarning, fmt.Sprintf("Failed to load capabilities: %v", err))
114			}
115		}()
116	
117		return nil
118	}
119	
120	// loadCapabilities loads tools, resources, and prompts from the MCP server
121	func (c *StdioClient) loadCapabilities(ctx context.Context) error {
122		// Load tools
123		if err := c.loadTools(ctx); err != nil {
124			return fmt.Errorf("failed to load tools: %w", err)
125		}
126	
127		// Load resources
128		if err := c.loadResources(ctx); err != nil {
129			c.log(LoggingLevelWarning, fmt.Sprintf("Failed to load resources: %v", err))
130		}
131	
132		// Load prompts
133		if err := c.loadPrompts(ctx); err != nil {
134			c.log(LoggingLevelWarning, fmt.Sprintf("Failed to load prompts: %v", err))
135		}
136	
137		return nil
138	}
139	
140	// loadTools loads available tools from the MCP server
141	func (c *StdioClient) loadTools(ctx context.Context) error {
142		if c.mcpClient == nil {
143			return fmt.Errorf("client not connected")
144		}
145	
146		toolsResult, err := c.mcpClient.ListTools(ctx, mcp.ListToolsRequest{})
147		if err != nil {
148			return fmt.Errorf("failed to list tools: %w", err)
149		}
150	
151		// Apply tool filtering
152		filteredTools := FilterTools(toolsResult.Tools, c.config.Options.ToolFilter)
153	
154		c.tools = filteredTools
155		c.log(LoggingLevelInfo, fmt.Sprintf("Loaded %d tools (filtered from %d)", len(c.tools), len(toolsResult.Tools)))
156	
157		return nil
158	}
159	
160	// loadResources loads available resources from the MCP server
161	func (c *StdioClient) loadResources(ctx context.Context) error {
162		if c.mcpClient == nil {
163			return fmt.Errorf("client not connected")
164		}
165	
166		resourcesResult, err := c.mcpClient.ListResources(ctx, mcp.ListResourcesRequest{})
167		if err != nil {
168			return fmt.Errorf("failed to list resources: %w", err)
169		}
170	
171		c.resources = resourcesResult.Resources
172		c.log(LoggingLevelInfo, fmt.Sprintf("Loaded %d resources", len(c.resources)))
173	
174		return nil
175	}
176	
177	// loadPrompts loads available prompts from the MCP server
178	func (c *StdioClient) loadPrompts(ctx context.Context) error {
179		if c.mcpClient == nil {
180			return fmt.Errorf("client not connected")
181		}
182	
183		promptsResult, err := c.mcpClient.ListPrompts(ctx, mcp.ListPromptsRequest{})
184		if err != nil {
185			return fmt.Errorf("failed to list prompts: %w", err)
186		}
187	
188		c.prompts = promptsResult.Prompts
189		c.log(LoggingLevelInfo, fmt.Sprintf("Loaded %d prompts", len(c.prompts)))
190	
191		return nil
192	}
193	
194	// CallTool calls a tool on the MCP server
195	func (c *StdioClient) CallTool(ctx context.Context, name string, arguments map[string]interface{}) (*mcp.CallToolResult, error) {
196		if c.mcpClient == nil {
197			return nil, fmt.Errorf("client not connected")
198		}
199	
200		// Check if tool exists and is allowed
201		var toolFound bool
202		for _, tool := range c.tools {
203			if tool.Name == name {
204				toolFound = true
205				break
206			}
207		}
208	
209		if !toolFound {
210			return nil, fmt.Errorf("tool '%s' not found or not allowed", name)
211		}
212	
213		// Validate that the tool hasn't been flagged as malicious
214		c.log(LoggingLevelDebug, fmt.Sprintf("Calling tool: %s with arguments: %+v", name, arguments))
215	
216		// Log the type of each argument for debugging
217		for key, value := range arguments {
218			c.log(LoggingLevelDebug, fmt.Sprintf("Argument %s: type=%T, value=%+v", key, value, value))
219		}
220	
221		// For debugging, keep the original arguments as-is for the MCP call
222		// The MCP library should handle the conversion properly
223		callReq := mcp.CallToolRequest{}
224		callReq.Params.Name = name
225		callReq.Params.Arguments = arguments
226	
227		result, err := c.mcpClient.CallTool(ctx, callReq)
228		if err != nil {
229			c.log(LoggingLevelError, fmt.Sprintf("Tool call failed for %s: %v", name, err))
230			c.log(LoggingLevelError, fmt.Sprintf("Arguments were: %+v", arguments))
231	
232			// Log detailed argument types for debugging
233			for key, value := range arguments {
234				c.log(LoggingLevelError, fmt.Sprintf("Failed arg %s: type=%T, value=%+v", key, value, value))
235			}
236	
237			return nil, fmt.Errorf("tool call failed: %w", err)
238		}
239	
240		c.log(LoggingLevelDebug, fmt.Sprintf("Tool call successful: %s", name))
241		if result != nil && result.Content != nil {
242			c.log(LoggingLevelDebug, fmt.Sprintf("Tool result content length: %d items", len(result.Content)))
243		}
244		return result, nil
245	}
246	
247	// ReadResource reads a resource from the MCP server
248	func (c *StdioClient) ReadResource(ctx context.Context, uri string) (*mcp.ReadResourceResult, error) {
249		if c.mcpClient == nil {
250			return nil, fmt.Errorf("client not connected")
251		}
252	
253		c.log(LoggingLevelDebug, fmt.Sprintf("Reading resource: %s", uri))
254	
255		readReq := mcp.ReadResourceRequest{}
256		readReq.Params.URI = uri
257	
258		result, err := c.mcpClient.ReadResource(ctx, readReq)
259		if err != nil {
260			c.log(LoggingLevelError, fmt.Sprintf("Resource read failed: %v", err))
261			return nil, fmt.Errorf("resource read failed: %w", err)
262		}
263	
264		c.log(LoggingLevelDebug, fmt.Sprintf("Resource read successful: %s", uri))
265		return result, nil
266	}
267	
268	// GetPrompt gets a prompt from the MCP server
269	func (c *StdioClient) GetPrompt(ctx context.Context, name string, arguments map[string]interface{}) (*mcp.GetPromptResult, error) {
270		if c.mcpClient == nil {
271			return nil, fmt.Errorf("client not connected")
272		}
273	
274		c.log(LoggingLevelDebug, fmt.Sprintf("Getting prompt: %s", name))
275	
276		// Convert map[string]interface{} to map[string]string for MCP library compatibility
277		stringArgs := make(map[string]string)
278		for k, v := range arguments {
279			if str, ok := v.(string); ok {
280				stringArgs[k] = str
