319	// sendRequest sends an HTTP request to the MCP server
320	func (c *HTTPClient) sendRequest(ctx context.Context, endpoint string, payload interface{}) ([]byte, error) {
321		// Construct URL
322		requestURL := fmt.Sprintf("%s/%s", c.baseURL, endpoint)
323	
324		// Prepare request body
325		var body io.Reader
326		if payload != nil {
327			jsonData, err := json.Marshal(payload)
328			if err != nil {
329				return nil, fmt.Errorf("failed to marshal request: %w", err)
330			}
331			body = bytes.NewReader(jsonData)
332		}
333	
334		// Create HTTP request
