462			switch c := firstContent.(type) {
463			case *mcp.TextContent:
464				content = c.Text
465			case mcp.TextContent:
466				content = c.Text
467			case *mcp.ImageContent:
468				content = fmt.Sprintf("Image: %s", c.Data)
469			case mcp.ImageContent:
