498		if filter.Mode == "" || len(filter.List) == 0 {
499			return tools
500		}
501	
502		filtered := make([]mcp.Tool, 0)
503		for _, tool := range tools {
504			switch filter.Mode {
505			case "allow":
506				if toolInList(tool.Name, filter.List) {
507					filtered = append(filtered, tool)
508				}
509			case "block":
510				if !toolInList(tool.Name, filter.List) {
511					filtered = append(filtered, tool)
