// Package tools provides tool selection and filtering capabilities
// for the semantic router.
package tools

import (
	"sort"
	"strings"
	"unicode"

	"github.com/openai/openai-go"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
)

// FilterAndRankTools applies advanced filtering and ranking to tool candidates.
func FilterAndRankTools(query string, candidates []ToolSimilarity, topK int, advanced *config.AdvancedToolFilteringConfig, selectedCategory string) []openai.ChatCompletionToolParam {
	return FilterAndRankToolsWithConversation(query, candidates, topK, advanced, selectedCategory, nil, 0)
}

// FilterAndRankToolsWithConversation is like FilterAndRankTools but supplies assistant tool-call
// history and decision confidence for hybrid_history retrieval.
func FilterAndRankToolsWithConversation(
	query string,
	candidates []ToolSimilarity,
	topK int,
	advanced *config.AdvancedToolFilteringConfig,
	selectedCategory string,
	toolHistory []string,
	decisionConfidence float64,
) []openai.ChatCompletionToolParam {
	if len(candidates) == 0 {
		return []openai.ChatCompletionToolParam{}
	}
	if advanced == nil || !advanced.Enabled {
		return selectTopKBySimilarity(candidates, topK)
	}

	filtered := applyAllowBlockFilters(candidates, advanced.AllowTools, advanced.BlockTools)
	filtered = applyCategoryFilter(filtered, advanced.UseCategoryFilter, selectedCategory)

	if config.IsHybridHistoryRetrieval(advanced) {
		return filterAndRankHybridHistory(query, filtered, topK, advanced, selectedCategory, toolHistory, decisionConfidence)
	}
	return filterAndRankWeightedLexical(query, filtered, topK, advanced, selectedCategory)
}

func filterAndRankWeightedLexical(query string, filtered []ToolSimilarity, topK int, advanced *config.AdvancedToolFilteringConfig, selectedCategory string) []openai.ChatCompletionToolParam {
	queryTokens := tokenize(query)
	querySet := tokenSet(queryTokens)
	queryTokenCount := len(queryTokens)

	weights := resolveWeights(advanced.Weights)
	weightSum := weights.embed + weights.lexical + weights.tag + weights.name + weights.category
	minOverlap, minCombined := minLexicalOverlapAndMinCombined(advanced)

	scored := make([]scoredCandidate, 0, len(filtered))
	for _, candidate := range filtered {
		if combined, ok := weightedCandidateCombinedScore(
			candidate, querySet, queryTokenCount, selectedCategory, weights, weightSum, minOverlap, minCombined,
		); ok {
			scored = append(scored, scoredCandidate{ToolSimilarity: candidate, CombinedScore: combined})
		}
	}

	if len(scored) == 0 {
		return []openai.ChatCompletionToolParam{}
	}

	sortScoredCandidatesByCombinedThenSimilarity(scored)

	return topKToolsFromScored(scored, topK)
}

func minLexicalOverlapAndMinCombined(advanced *config.AdvancedToolFilteringConfig) (minOverlap int, minCombined float32) {
	if advanced.MinLexicalOverlap != nil {
		minOverlap = *advanced.MinLexicalOverlap
	}
	if advanced.MinCombinedScore != nil {
		minCombined = *advanced.MinCombinedScore
	}
	return minOverlap, minCombined
}

func weightedCandidateCombinedScore(
	candidate ToolSimilarity,
	querySet map[string]struct{},
	queryTokenCount int,
	selectedCategory string,
	weights resolvedWeights,
	weightSum float32,
	minOverlap int,
	minCombined float32,
) (float32, bool) {
	nameTokens := tokenize(candidate.Entry.Tool.Function.Name)
	descriptionTokens := tokenize(candidate.Entry.Description)
	categoryTokens := tokenize(candidate.Entry.Category)
	tagTokens := collectTagTokens(candidate.Entry.Tags)

	lexicalTokens := make([]string, 0, len(nameTokens)+len(descriptionTokens)+len(categoryTokens))
	lexicalTokens = append(lexicalTokens, nameTokens...)
	lexicalTokens = append(lexicalTokens, descriptionTokens...)
	lexicalTokens = append(lexicalTokens, categoryTokens...)

	lexicalOverlap := countOverlap(querySet, lexicalTokens)
	if minOverlap > 0 && lexicalOverlap < minOverlap {
		return 0, false
	}

	lexicalScore := scoreOverlap(queryTokenCount, lexicalOverlap)
	tagScore := scoreOverlap(len(tagTokens), countOverlap(querySet, tagTokens))
	nameScore := nameMatchScore(nameTokens, querySet)
	categoryScore := categoryMatchScore(selectedCategory, candidate.Entry.Category)
	similarityScore := clamp01(candidate.Similarity)

	var combined float32
	if weightSum > 0 {
		combined = (weights.embed*similarityScore +
			weights.lexical*lexicalScore +
			weights.tag*tagScore +
			weights.name*nameScore +
			weights.category*categoryScore) / weightSum
	}
	if combined < minCombined {
		return 0, false
	}
	return combined, true
}

func sortScoredCandidatesByCombinedThenSimilarity(scored []scoredCandidate) {
	sort.Slice(scored, func(i, j int) bool {
		if scored[i].CombinedScore == scored[j].CombinedScore {
			if scored[i].Similarity == scored[j].Similarity {
				return scored[i].Entry.Tool.Function.Name < scored[j].Entry.Tool.Function.Name
			}
			return scored[i].Similarity > scored[j].Similarity
		}
		return scored[i].CombinedScore > scored[j].CombinedScore
	})
}

func topKToolsFromScored(scored []scoredCandidate, topK int) []openai.ChatCompletionToolParam {
	limit := topK
	if limit <= 0 || limit > len(scored) {
		limit = len(scored)
	}
	out := make([]openai.ChatCompletionToolParam, 0, limit)
	for i := 0; i < limit; i++ {
		out = append(out, scored[i].Entry.Tool)
	}
	return out
}

type scoredCandidate struct {
	ToolSimilarity
	CombinedScore float32
}

type resolvedWeights struct {
	embed    float32
	lexical  float32
	tag      float32
	name     float32
	category float32
}

func resolveWeights(weights config.ToolFilteringWeights) resolvedWeights {
	resolved := resolvedWeights{}
	anySet := false
	if weights.Embed != nil {
		resolved.embed = *weights.Embed
		anySet = true
	}
	if weights.Lexical != nil {
		resolved.lexical = *weights.Lexical
		anySet = true
	}
	if weights.Tag != nil {
		resolved.tag = *weights.Tag
		anySet = true
	}
	if weights.Name != nil {
		resolved.name = *weights.Name
		anySet = true
	}
	if weights.Category != nil {
		resolved.category = *weights.Category
		anySet = true
	}

	if !anySet {
		resolved.embed = 1
	}

	return resolved
}

func selectTopKBySimilarity(candidates []ToolSimilarity, topK int) []openai.ChatCompletionToolParam {
	if len(candidates) == 0 {
		return []openai.ChatCompletionToolParam{}
	}

	sorted := make([]ToolSimilarity, len(candidates))
	copy(sorted, candidates)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Similarity > sorted[j].Similarity
	})

	limit := topK
	if limit <= 0 || limit > len(sorted) {
		limit = len(sorted)
	}

	selected := make([]openai.ChatCompletionToolParam, 0, limit)
	for i := 0; i < limit; i++ {
		selected = append(selected, sorted[i].Entry.Tool)
	}

	return selected
}

func applyAllowBlockFilters(candidates []ToolSimilarity, allowList []string, blockList []string) []ToolSimilarity {
	allowSet := normalizeNameSet(allowList)
	blockSet := normalizeNameSet(blockList)

	filtered := make([]ToolSimilarity, 0, len(candidates))
	for _, candidate := range candidates {
		name := strings.ToLower(candidate.Entry.Tool.Function.Name)
		if len(allowSet) > 0 {
			if _, ok := allowSet[name]; !ok {
				continue
			}
		}
		if _, blocked := blockSet[name]; blocked {
			continue
		}
		filtered = append(filtered, candidate)
	}

	return filtered
}

func applyCategoryFilter(candidates []ToolSimilarity, useCategoryFilter *bool, selectedCategory string) []ToolSimilarity {
	if useCategoryFilter == nil || !*useCategoryFilter {
		return candidates
	}
	if strings.TrimSpace(selectedCategory) == "" {
		return candidates
	}

	selectedCategory = strings.ToLower(strings.TrimSpace(selectedCategory))
	filtered := make([]ToolSimilarity, 0, len(candidates))
	for _, candidate := range candidates {
		candidateCategory := strings.ToLower(strings.TrimSpace(candidate.Entry.Category))
		if candidateCategory == selectedCategory {
			filtered = append(filtered, candidate)
		}
	}

	if len(filtered) == 0 {
		return candidates
	}
	return filtered
}

func normalizeNameSet(names []string) map[string]struct{} {
	if len(names) == 0 {
		return map[string]struct{}{}
	}

	set := make(map[string]struct{}, len(names))
	for _, name := range names {
		trimmed := strings.TrimSpace(strings.ToLower(name))
		if trimmed == "" {
			continue
		}
		set[trimmed] = struct{}{}
	}
	return set
}

func tokenize(input string) []string {
	if input == "" {
		return []string{}
	}

	lower := strings.ToLower(input)
	tokens := make([]string, 0)
	var builder strings.Builder

	flush := func() {
		if builder.Len() == 0 {
			return
		}
		tokens = append(tokens, builder.String())
		builder.Reset()
	}

	for _, r := range lower {
		if unicode.IsLetter(r) || unicode.IsNumber(r) {
			builder.WriteRune(r)
			continue
		}
		flush()
	}
	flush()

	return tokens
}

func tokenSet(tokens []string) map[string]struct{} {
	set := make(map[string]struct{}, len(tokens))
	for _, token := range tokens {
		if token == "" {
			continue
		}
		set[token] = struct{}{}
	}
	return set
}

func collectTagTokens(tags []string) []string {
	if len(tags) == 0 {
		return []string{}
	}

	collected := make([]string, 0, len(tags))
	for _, tag := range tags {
		collected = append(collected, tokenize(tag)...)
	}
	return collected
}

func countOverlap(querySet map[string]struct{}, tokens []string) int {
	if len(querySet) == 0 || len(tokens) == 0 {
		return 0
	}

	seen := make(map[string]struct{})
	count := 0
	for _, token := range tokens {
		if token == "" {
			continue
		}
		if _, ok := querySet[token]; !ok {
			continue
		}
		if _, already := seen[token]; already {
			continue
		}
		seen[token] = struct{}{}
		count++
	}
	return count
}

func scoreOverlap(denominator int, overlap int) float32 {
	if denominator <= 0 || overlap <= 0 {
		return 0
	}
	return float32(overlap) / float32(denominator)
}

func nameMatchScore(nameTokens []string, querySet map[string]struct{}) float32 {
	if len(nameTokens) == 0 || len(querySet) == 0 {
		return 0
	}
	for _, token := range nameTokens {
		if _, ok := querySet[token]; !ok {
			return 0
		}
	}
	return 1
}

func categoryMatchScore(selectedCategory string, toolCategory string) float32 {
	if strings.TrimSpace(selectedCategory) == "" || strings.TrimSpace(toolCategory) == "" {
		return 0
	}
	if strings.EqualFold(strings.TrimSpace(selectedCategory), strings.TrimSpace(toolCategory)) {
		return 1
	}
	return 0
}

func clamp01(value float32) float32 {
	return max(float32(0), min(float32(1), value))
}

package config

const (
	DecisionPluginTools = "tools"

	ToolsPluginModeNone        = "none"
	ToolsPluginModePassthrough = "passthrough"
	ToolsPluginModeFiltered    = "filtered"

	// ToolsStrategyDefault is the strategy name used when no explicit strategy
	// is configured.  It resolves to the embedding-similarity retriever.
	ToolsStrategyDefault = "default"

	// Dynamic retrieval strategy names.  These are decision-scoped knobs that
	// describe how the retriever combines semantic similarity with optional
	// per-decision tool-call history.  Behavior is implemented in subsequent
	// issues; this contract only fixes the configuration surface.
	DynamicRetrievalStrategySemanticOnly  = "semantic_only"
	DynamicRetrievalStrategyHybridHistory = "hybrid_history"
)

// ToolsPluginConfig represents per-decision tool handling.
// It owns both request tool filtering and semantic tool selection behavior.
type ToolsPluginConfig struct {
	Enabled           bool     `json:"enabled" yaml:"enabled"`
	Mode              string   `json:"mode,omitempty" yaml:"mode,omitempty"`
	SemanticSelection *bool    `json:"semantic_selection,omitempty" yaml:"semantic_selection,omitempty"`
	AllowTools        []string `json:"allow_tools,omitempty" yaml:"allow_tools,omitempty"`
	BlockTools        []string `json:"block_tools,omitempty" yaml:"block_tools,omitempty"`
	// Strategy names the retriever strategy to use for semantic tool selection.
	// When empty, EffectiveStrategy returns ToolsStrategyDefault.
	// The value must match a name registered in the router's tools.Registry.
	Strategy string `json:"strategy,omitempty" yaml:"strategy,omitempty"`
	// DynamicRetrieval configures history-aware tool retrieval behavior.  When
	// nil or with Enabled=false, the existing semantic-similarity retriever is
	// used unchanged.  See issue #1832 for the contract scope; implementation
	// of the strategies and the persisted-priors layer is staged in #1839.
	DynamicRetrieval *DynamicRetrievalConfig `json:"dynamic_retrieval,omitempty" yaml:"dynamic_retrieval,omitempty"`
}

// DynamicRetrievalConfig is the decision-scoped contract for history-aware
// tool retrieval.  It is intentionally additive: when nil, when Enabled is
// false, or when omitted from configuration, the router behaves exactly as
// before this contract was introduced.
type DynamicRetrievalConfig struct {
	// Enabled gates the entire dynamic retrieval path.  When false, none of
	// the other fields are consulted and the validator skips range checks.
	Enabled bool `json:"enabled" yaml:"enabled"`
	// Strategy selects the retrieval algorithm.  Must be one of
	// DynamicRetrievalStrategySemanticOnly or DynamicRetrievalStrategyHybridHistory.
	// When empty, EffectiveStrategy returns DynamicRetrievalStrategySemanticOnly.
	Strategy string `json:"strategy,omitempty" yaml:"strategy,omitempty"`
	// HistoryWindow is the number of recent tool-call observations the
	// retriever may inspect when Strategy is hybrid_history.  Required to be
	// at least 1 when the hybrid strategy is active.  Ignored otherwise.
	HistoryWindow int `json:"history_window,omitempty" yaml:"history_window,omitempty"`
	// Weights blends the per-source signals when Strategy is hybrid_history.
	// When nil, sensible defaults are used by the retriever (semantic 1.0,
	// history 1.0, decision_prior 0.0, repetition_penalty 0.0).
	Weights *DynamicRetrievalWeights `json:"weights,omitempty" yaml:"weights,omitempty"`
	// MinHistoryConfidence is the per-decision confidence threshold below
	// which the retriever treats history evidence as too weak to use.  Must
	// be in [0.0, 1.0].
	MinHistoryConfidence float64 `json:"min_history_confidence,omitempty" yaml:"min_history_confidence,omitempty"`
	// FallbackOnLowConfidence, when true, instructs the retriever to fall
	// back to the semantic-only ranking whenever the history evidence does
	// not clear MinHistoryConfidence.
	FallbackOnLowConfidence bool `json:"fallback_on_low_confidence,omitempty" yaml:"fallback_on_low_confidence,omitempty"`
}

// DynamicRetrievalWeights holds the combination weights for the hybrid
// retriever.  Each weight is a non-negative scalar; the retriever normalizes
// internally before applying them.  Zero weights mean the corresponding
// signal is ignored.
type DynamicRetrievalWeights struct {
	Semantic          float64 `json:"semantic,omitempty" yaml:"semantic,omitempty"`
	History           float64 `json:"history,omitempty" yaml:"history,omitempty"`
	DecisionPrior     float64 `json:"decision_prior,omitempty" yaml:"decision_prior,omitempty"`
	RepetitionPenalty float64 `json:"repetition_penalty,omitempty" yaml:"repetition_penalty,omitempty"`
}

// GetToolsConfig returns the tools plugin configuration.
func (d *Decision) GetToolsConfig() *ToolsPluginConfig {
	result := &ToolsPluginConfig{}
	return decodeDecisionPlugin(d, DecisionPluginTools, result)
}

// EffectiveMode returns the defaulted tool-handling mode.
func (c *ToolsPluginConfig) EffectiveMode() string {
	if c == nil || c.Mode == "" {
		return ToolsPluginModePassthrough
	}
	return c.Mode
}

// EffectiveStrategy returns the retriever strategy name, defaulting to
// ToolsStrategyDefault when none is configured.
func (c *ToolsPluginConfig) EffectiveStrategy() string {
	if c == nil || c.Strategy == "" {
		return ToolsStrategyDefault
	}
	return c.Strategy
}

// SelectionEnabled reports whether semantic tool selection is allowed for this plugin.
func (c *ToolsPluginConfig) SelectionEnabled() bool {
	if c == nil || !c.Enabled || c.EffectiveMode() == ToolsPluginModeNone {
		return false
	}
	if c.SemanticSelection == nil {
		return true
	}
	return *c.SemanticSelection
}

// DynamicRetrievalEnabled reports whether the decision opts in to dynamic
// retrieval.  Returns false for nil receivers and for configurations where
// the dynamic_retrieval block is unset or disabled.
func (c *ToolsPluginConfig) DynamicRetrievalEnabled() bool {
	if c == nil || c.DynamicRetrieval == nil {
		return false
	}
	return c.DynamicRetrieval.Enabled
}

// EffectiveStrategy returns the dynamic retrieval strategy, defaulting to
// DynamicRetrievalStrategySemanticOnly when the receiver is nil or has no
// strategy configured.  The default mirrors the pre-#1832 behavior so that
// callers can rely on a non-empty strategy name without nil-checking.
func (d *DynamicRetrievalConfig) EffectiveStrategy() string {
	if d == nil || d.Strategy == "" {
		return DynamicRetrievalStrategySemanticOnly
	}
	return d.Strategy
}

