1	package extproc
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"strconv"
8		"strings"
9		"time"
10	
11		core "github.com/envoyproxy/go-control-plane/envoy/config/core/v3"
12		ext_proc "github.com/envoyproxy/go-control-plane/envoy/service/ext_proc/v3"
13		"github.com/openai/openai-go"
14		"github.com/openai/openai-go/packages/param"
15	
16		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
17		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/headers"
18		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
19		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
20		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/tools"
21	)
22	
23	// handleToolSelectionForRequest handles tool selection for the request.
24	func (r *OpenAIRouter) handleToolSelectionForRequest(openAIRequest *openai.ChatCompletionNewParams, response *ext_proc.ProcessingResponse, ctx *RequestContext) {
25		userContent, nonUserMessages := extractUserAndNonUserContent(openAIRequest)
26		if err := r.handleToolSelection(openAIRequest, userContent, nonUserMessages, &response, ctx); err != nil {
27			logging.Errorf("Error in tool selection: %v", err)
28			// Continue without failing the request
29		}
30		if clearToolChoiceWhenNoTools(openAIRequest) {
31			if err := r.updateRequestWithTools(openAIRequest, &response, ctx); err != nil {
32				logging.Errorf("Error clearing invalid tool_choice without tools: %v", err)
33			}
34		}
35	}
36	
37	func (r *OpenAIRouter) applySelectedTools(
38		openAIRequest *openai.ChatCompletionNewParams,
39		selectedTools []openai.ChatCompletionToolParam,
40		strategyID string,
41		confidence float32,
42		latency time.Duration,
43		classificationText string,
44		fallbackToEmptyOverride *bool,
45	) error {
46		fallbackEmpty := r.Config.Tools.FallbackToEmpty
47		if fallbackToEmptyOverride != nil {
48			fallbackEmpty = *fallbackToEmptyOverride
49		}
50	
51		if len(selectedTools) == 0 {
52			if fallbackEmpty {
53				logging.Infof("No suitable tools found, falling back to no tools")
54				openAIRequest.Tools = nil
55			} else {
56				logging.Infof("No suitable tools found above threshold")
57				openAIRequest.Tools = []openai.ChatCompletionToolParam{}
58			}
59			return nil
60		}
61		sdkTools, err := convertToSDKTools(selectedTools)
62		if err != nil {
63			metrics.RecordRequestError(openAIRequest.Model, "serialization_error")
64			return err
65		}
66		openAIRequest.Tools = sdkTools
67		logging.Infof("Auto-selected %d tools via strategy %q (confidence=%.3f, latency=%s) for query: %s",
68			len(sdkTools), strategyID, confidence, latency.Round(time.Millisecond),
69			logging.ContentDescriptor(classificationText))
70		return nil
71	}
72	
73	// handleEarlyToolModes applies the tool plugin mode (none, filtered, passthrough)
74	// and returns true if the caller should proceed to semantic tool selection.
75	// If it returns false, the request has already been updated and the caller must return nil.
76	func (r *OpenAIRouter) handleEarlyToolModes(
77		openAIRequest *openai.ChatCompletionNewParams,
78		response **ext_proc.ProcessingResponse,
79		ctx *RequestContext,
80		toolsCfg *config.ToolsPluginConfig,
81	) (bool, error) {
82		switch toolsCfg.EffectiveMode() {
83		case config.ToolsPluginModeNone:
84			logging.Infof("[ToolsPlugin] Decision %q has mode=none, stripping all tools", ctx.VSRSelectedDecision.Name)
85			openAIRequest.Tools = nil
86			if err := r.updateRequestWithTools(openAIRequest, response, ctx); err != nil {
87				return false, err
88			}
89			return false, nil
90	
91		case config.ToolsPluginModeFiltered:
92			openAIRequest.Tools = filterToolsByDecisionPolicy(openAIRequest.Tools, toolsCfg.AllowTools, toolsCfg.BlockTools)
93			if openAIRequest.ToolChoice.OfAuto.Value != "auto" {
94				logging.Infof("[ToolsPlugin] Decision %q filtered explicit tools to %d entries", ctx.VSRSelectedDecision.Name, len(openAIRequest.Tools))
95				if err := r.updateRequestWithTools(openAIRequest, response, ctx); err != nil {
96					return false, err
97				}
98				return false, nil
99			}
100			return true, nil
101	
102		case config.ToolsPluginModePassthrough:
103			return openAIRequest.ToolChoice.OfAuto.Value == "auto", nil
104	
105		default:
106			return false, fmt.Errorf("tools plugin: unsupported mode %q", toolsCfg.Mode)
107		}
108	}
109	
110	// runSemanticToolSelection performs the retrieval, observability reporting,
111	// fallback handling and final tool application after the earlier mode checks
112	// have determined that semantic selection should run.
113	func (r *OpenAIRouter) runSemanticToolSelection(
114		openAIRequest *openai.ChatCompletionNewParams,
115		classificationText string,
116		historySummary string,
117		response **ext_proc.ProcessingResponse,
118		ctx *RequestContext,
119		toolsCfg *config.ToolsPluginConfig,
120	) error {
121		selectedTools, strategyID, confidence, latency, toolErr := r.findToolsForQuery(openAIRequest, classificationText, historySummary, ctx, toolsCfg)
122	
123		emitToolObservability(response, ctx, strategyID, confidence, latency)
124		metrics.RecordToolsRetrieval(strategyID, latency.Seconds())
125	
126		if toolErr != nil {
127			return r.handleToolSelectionError(openAIRequest, response, ctx, toolErr, r.Config.Tools.FallbackToEmpty)
128		}
129	
130		if err := r.applySelectedTools(openAIRequest, selectedTools, strategyID, confidence, latency, classificationText, nil); err != nil {
131			return err
132		}
133		return r.updateRequestWithTools(openAIRequest, response, ctx)
134	}
135	
136	func (r *OpenAIRouter) handleToolSelectionError(
137		openAIRequest *openai.ChatCompletionNewParams,
138		response **ext_proc.ProcessingResponse,
139		ctx *RequestContext,
140		toolErr error,
141		fallbackToEmpty bool,
142	) error {
143		if fallbackToEmpty {
144			logging.Warnf("Tool selection failed, falling back to no tools: %v", toolErr)
145			openAIRequest.Tools = nil
146			return r.updateRequestWithTools(openAIRequest, response, ctx)
147		}
148		metrics.RecordRequestError(getModelFromCtx(ctx), "classification_failed")
149		return toolErr
150	}
151	
152	// handleToolSelection handles automatic tool selection based on semantic similarity.
153	func (r *OpenAIRouter) handleToolSelection(
154		openAIRequest *openai.ChatCompletionNewParams,
155		userContent string,
156		nonUserMessages []string,
157		response **ext_proc.ProcessingResponse,
158		ctx *RequestContext,
159	) error {
160		if ctx.VSRSelectedDecision == nil {
161			return nil
162		}
163	
164		tsPlugin := ctx.VSRSelectedDecision.GetToolSelectionConfig()
165		toolsCfg := resolveDecisionToolsConfig(ctx)
166	
167		handled, err := r.handleToolSelectionDecisionPlugin(openAIRequest, userContent, nonUserMessages, response, ctx, tsPlugin, toolsCfg)
168		if err != nil {
169			return err
170		}
171		if handled {
172			return nil
173		}
174	
175		if toolsCfg == nil || !toolsCfg.Enabled {
176			return nil
177		}
178	
179		shouldContinue, err := r.handleEarlyToolModes(openAIRequest, response, ctx, toolsCfg)
180		if err != nil {
181			return err
182		}
183		if !shouldContinue {
184			return nil
185		}
186	
187		if !toolsCfg.SelectionEnabled() {
188			return r.updateRequestWithTools(openAIRequest, response, ctx)
189		}
190	
191		classificationText, historySummary, ok := buildToolClassificationText(userContent, nonUserMessages)
192		if !ok {
193			logging.Infof("No content available for tool classification")
194			return nil
195		}
196	
197		if !r.ToolsDatabase.IsEnabled() {
198			logging.Infof("Tools database is disabled")
199			return nil
200		}
201	
202		return r.runSemanticToolSelection(openAIRequest, classificationText, historySummary, response, ctx, toolsCfg)
203	}
204	
205	func (r *OpenAIRouter) handleToolSelectionDecisionPlugin(
206		openAIRequest *openai.ChatCompletionNewParams,
207		userContent string,
208		nonUserMessages []string,
209		response **ext_proc.ProcessingResponse,
210		ctx *RequestContext,
211		tsPlugin *config.ToolSelectionPluginConfig,
212		toolsCfg *config.ToolsPluginConfig,
213	) (bool, error) {
214		if tsPlugin == nil || !tsPlugin.Enabled {
215			return false, nil
216		}
217		earlyCfg := toolsCfg
218		if earlyCfg == nil || !earlyCfg.Enabled {
219			earlyCfg = &config.ToolsPluginConfig{Enabled: true, Mode: config.ToolsPluginModePassthrough}
220		}
221	
222		shouldContinue, err := r.handleEarlyToolModes(openAIRequest, response, ctx, earlyCfg)
223		if err != nil {
224			return false, err
225		}
226		if !shouldContinue {
227			return true, nil
228		}
229	
230		classificationText, historySummary, ok := buildToolClassificationText(userContent, nonUserMessages)
231		if !ok {
232			logging.Infof("No content available for tool classification")
233			return true, nil
234		}
235	
236		mode := strings.TrimSpace(tsPlugin.Mode)
237		if mode == "" {
238			mode = config.ToolSelectionModeAdd
239		}
240	
241		switch mode {
242		case config.ToolSelectionModeFilter:
243			return true, r.runToolSelectionPluginFilter(openAIRequest, classificationText, response, ctx, tsPlugin)
244		case config.ToolSelectionModeAdd:
245			return true, r.runToolSelectionPluginAdd(openAIRequest, classificationText, historySummary, response, ctx, tsPlugin, toolsCfg)
246		default:
247			return false, fmt.Errorf("tool_selection plugin: unsupported mode %q", mode)
248		}
249	}
250	
251	func (r *OpenAIRouter) retrievalViaEmbeddingDatabase(strategyID string, in tools.RetrievalInput, db *tools.ToolsDatabase) (tools.RetrievalResult, error) {
252		pool := in.EffectivePoolSize()
253		results, err := db.FindSimilarToolsWithScoresMinSimilarity(in.Query, pool, in.MinSimilarity)
254		if err != nil {
255			return tools.RetrievalResult{StrategyID: strategyID}, err
256		}
257		confidence := float32(0)
258		if len(results) > 0 {
259			confidence = results[0].Similarity
260		}
261		return tools.RetrievalResult{
262			Tools:      results,
263			Confidence: confidence,
264			StrategyID: strategyID,
265		}, nil
266	}
267	
268	// executeRetrieval resolves the retriever for strategyID from the registry and
269	// runs it with in. If the registry is nil or the strategy is not found, it falls
270	// back to ToolsDatabase directly and marks the returned StrategyID with "-fallback".
271	//
272	// scopedEmbDB, when non-nil, forces retrieval against that database via embedding
273	// similarity (registry strategies are skipped).
274	func (r *OpenAIRouter) executeRetrieval(ctx context.Context, strategyID string, in tools.RetrievalInput, scopedEmbDB *tools.ToolsDatabase) (tools.RetrievalResult, error) {
275		if scopedEmbDB != nil {
276			return r.retrievalViaEmbeddingDatabase(strategyID+"-scoped", in, scopedEmbDB)
277		}
278		if r.ToolsRegistry != nil {
279			if retriever, ok := r.ToolsRegistry.Get(strategyID); ok {
280				return retriever.Retrieve(ctx, in)
281			}
282	
283			// Named strategy not found — try "default" before falling back to DB
284			if retriever, ok := r.ToolsRegistry.Get(tools.StrategyDefault); ok {
285				logging.Warnf("[ToolsPlugin] strategy %q not found, falling back to default", strategyID)
286				result, err := retriever.Retrieve(ctx, in)
287				result.StrategyID = strategyID + "-fallback"
288				return result, err
289			}
290	
291			logging.Warnf("[ToolsPlugin] strategy %q not found in registry, using ToolsDatabase directly", strategyID)
292		} else {
293			logging.Warnf("[ToolsPlugin] registry not initialized for strategy %q, using ToolsDatabase directly", strategyID)
294		}
295	
296		pool := in.EffectivePoolSize()
297		results, err := r.ToolsDatabase.FindSimilarToolsWithScoresMinSimilarity(in.Query, pool, in.MinSimilarity)
298		if err != nil {
299			return tools.RetrievalResult{StrategyID: strategyID + "-fallback"}, err
300		}
301	
302		confidence := float32(0)
303		if len(results) > 0 {
304			confidence = results[0].Similarity
305		}
306	
307		return tools.RetrievalResult{
308			Tools:      results,
309			Confidence: confidence,
310			StrategyID: strategyID + "-fallback",
311		}, nil
312	}
313	
314	// findToolsForQuery resolves the retriever strategy from the registry, executes
315	// retrieval, applies advanced filtering, and returns the final tool list together
316	// with the strategy name, top-1 confidence score, and retrieval wall-clock time.
317	func (r *OpenAIRouter) findToolsForQuery(
318		openAIRequest *openai.ChatCompletionNewParams,
319		query, historySummary string,
320		ctx *RequestContext,
321		toolsCfg *config.ToolsPluginConfig,
322	) ([]openai.ChatCompletionToolParam, string, float32, time.Duration, error) {
323		topK := r.Config.Tools.TopK
324		if topK <= 0 {
325			topK = 3
326		}
327		advanced := mergeAdvancedToolFiltering(r.Config.Tools.AdvancedFiltering, toolsCfg)
328		return r.findToolsForQueryExt(openAIRequest, query, historySummary, ctx, toolsCfg, topK, advanced, toolsCfg.EffectiveStrategy(), nil, r.Config.Tools.SimilarityThreshold)
329	}
330	
331	func (r *OpenAIRouter) findToolsForQueryExt(
332		openAIRequest *openai.ChatCompletionNewParams,
333		query, historySummary string,
334		ctx *RequestContext,
335		toolsCfg *config.ToolsPluginConfig,
336		topK int,
337		advanced *config.AdvancedToolFilteringConfig,
338		strategyID string,
339		scopedEmbDB *tools.ToolsDatabase,
340		minSimilarity *float32,
341	) ([]openai.ChatCompletionToolParam, string, float32, time.Duration, error) {
342		if topK <= 0 {
343			topK = 3
344		}
345	
346		poolSize := resolveCandidatePoolSize(r.Config.Tools.AdvancedFiltering, topK)
347		if advanced != nil && advanced.Enabled {
348			poolSize = resolveCandidatePoolSize(advanced, topK)
349		}
350	
351		retrievalIn := newToolRetrievalInput(query, historySummary, topK, poolSize, ctx, minSimilarity)
352	
353		retrievalCtx := context.Background()
354		if ctx != nil && ctx.TraceContext != nil {
355			retrievalCtx = ctx.TraceContext
356		}
357	
358		start := time.Now()
359		retrieved, err := r.executeRetrieval(retrievalCtx, strategyID, retrievalIn, scopedEmbDB)
360		latency := time.Since(start)
361	
362		if err != nil {
363			return nil, retrieved.StrategyID, 0, latency, err
364		}
365	
366		if advanced == nil || !advanced.Enabled {
367			return selectTopKTools(retrieved.Tools, topK), retrieved.StrategyID, retrieved.Confidence, latency, nil
368		}
369	
370		if config.IsHybridHistoryRetrieval(advanced) {
371			transition := extractToolTransitionContextFromRequest(openAIRequest, config.ResolveHybridHistoryHorizon(advanced), ctx)
372			decisionConfidence := float64(0)
373			if ctx != nil {
374				decisionConfidence = float64(ctx.VSRSelectedDecisionConfidence)
375			}
376			selected := tools.FilterAndRankToolsWithConversation(
377				query,
378				retrieved.Tools,
379				topK,
380				advanced,
381				resolveCategory(advanced, ctx),
382				transition.RecentToolNames,
383				decisionConfidence,
384			)
385			return selected, retrieved.StrategyID, retrieved.Confidence, latency, nil
386		}
387	
388		selected := tools.FilterAndRankTools(query, retrieved.Tools, topK, advanced, resolveCategory(advanced, ctx))
389		return selected, retrieved.StrategyID, retrieved.Confidence, latency, nil
390	}
391	
392	// emitToolObservability writes the three x-vsr-tools-* headers into the
393	// in-flight ProcessingResponse so they reach the client as response headers.
394	// Per the v0.4 contract (#2205) these are intermediate observability details
395	// demoted off the default surface: they are emitted only when the request opted
396	// into debug headers via x-vsr-debug. The Prometheus tools-retrieval metric is
397	// recorded by the caller and stays unconditional.
398	func emitToolObservability(response **ext_proc.ProcessingResponse, ctx *RequestContext, strategyID string, confidence float32, latency time.Duration) {
399		if response == nil || *response == nil {
400			return
401		}
402		if !debugHeadersRequested(ctx) {
403			return
404		}
405		commonResponse := ensureRequestBodyCommonResponse(response)
406		if commonResponse.HeaderMutation == nil {
407			commonResponse.HeaderMutation = &ext_proc.HeaderMutation{}
408		}
409		setHeaderValue(commonResponse.HeaderMutation, headers.VSRToolsStrategy, strategyID)
410		setHeaderValue(commonResponse.HeaderMutation, headers.VSRToolsConfidence, strconv.FormatFloat(float64(confidence), 'f', 4, 32))
411		setHeaderValue(commonResponse.HeaderMutation, headers.VSRToolsLatencyMs, strconv.FormatInt(latency.Milliseconds(), 10))
412	}
413	
414	// selectTopKTools returns the top-K entries from candidates by similarity
415	// without applying advanced filtering.
416	func selectTopKTools(candidates []tools.ToolSimilarity, topK int) []openai.ChatCompletionToolParam {
417		limit := topK
418		if limit <= 0 || limit > len(candidates) {
419			limit = len(candidates)
420		}
421		selected := make([]openai.ChatCompletionToolParam, 0, limit)
422		for i := 0; i < limit; i++ {
423			selected = append(selected, candidates[i].Entry.Tool)
424		}
425		return selected
426	}
427	
428	func resolveCandidatePoolSize(advanced *config.AdvancedToolFilteringConfig, topK int) int {
429		if advanced == nil {
430			return max(topK*tools.DefaultCandidatePoolMultiplier, tools.DefaultCandidatePoolMin)
431		}
432		var size int
433		switch {
434		case advanced.CandidatePoolSize != nil && *advanced.CandidatePoolSize > 0:
435			size = *advanced.CandidatePoolSize
436		case advanced.CandidatePoolSize == nil:
437			size = max(topK*tools.DefaultCandidatePoolMultiplier, tools.DefaultCandidatePoolMin)
438		default:
439			size = topK
440		}
441		if size < topK {
442			size = topK
443		}
444		return size
445	}
446	
447	func newToolRetrievalInput(
448		query, historySummary string,
449		topK, poolSize int,
450		ctx *RequestContext,
451		minSimilarity *float32,
452	) tools.RetrievalInput {
453		in := tools.RetrievalInput{
454			Query:          query,
455			HistorySummary: historySummary,
456			TopK:           topK,
457			PoolSize:       poolSize,
458			MinSimilarity:  minSimilarity,
459		}
460		if ctx == nil {
461			return in
462		}
463		in.Category = ctx.VSRSelectedCategory
464		in.DecisionName = ctx.VSRSelectedDecisionName
465		if ctx.VSRSelectedDecision != nil && in.DecisionName == "" {
466			in.DecisionName = ctx.VSRSelectedDecision.Name
467		}
468		in.DecisionConfidence = ctx.VSRSelectedDecisionConfidence
469		return in
470	}
471	
472	func resolveCategory(advanced *config.AdvancedToolFilteringConfig, ctx *RequestContext) string {
473		cat := ctx.VSRSelectedCategory
474		if advanced.UseCategoryFilter == nil || !*advanced.UseCategoryFilter || cat == "" {
475			return cat
476		}
477		if advanced.CategoryConfidenceThreshold != nil &&
478			ctx.VSRSelectedDecisionConfidence < float64(*advanced.CategoryConfidenceThreshold) {
479			return ""
480		}
481		return cat
482	}
483	
484	func resolveDecisionToolsConfig(ctx *RequestContext) *config.ToolsPluginConfig {
485		if ctx == nil || ctx.VSRSelectedDecision == nil {
486			return nil
487		}
488		return ctx.VSRSelectedDecision.GetToolsConfig()
489	}
490	
491	func mergeAdvancedToolFiltering(base *config.AdvancedToolFilteringConfig, toolsCfg *config.ToolsPluginConfig) *config.AdvancedToolFilteringConfig {
492		if toolsCfg == nil || toolsCfg.EffectiveMode() != config.ToolsPluginModeFiltered {
493			return base
494		}
495		allowTools, blockTools := mergeToolFilters(base, toolsCfg)
496		if base == nil {
497			return &config.AdvancedToolFilteringConfig{
498				Enabled:    true,
499				AllowTools: allowTools,
500				BlockTools: blockTools,
501			}
502		}
503		merged := *base
504		merged.AllowTools = allowTools
505		merged.BlockTools = blockTools
506		return &merged
507	}
508	
509	func mergeToolFilters(base *config.AdvancedToolFilteringConfig, toolsCfg *config.ToolsPluginConfig) ([]string, []string) {
510		globalAllow := []string(nil)
511		globalBlock := []string(nil)
512		if base != nil {
513			globalAllow = append(globalAllow, base.AllowTools...)
514			globalBlock = append(globalBlock, base.BlockTools...)
515		}
516		pluginAllow := append([]string(nil), toolsCfg.AllowTools...)
517		pluginBlock := append([]string(nil), toolsCfg.BlockTools...)
518		return intersectToolAllowLists(globalAllow, pluginAllow), unionToolBlockLists(globalBlock, pluginBlock)
519	}
520	
521	func intersectToolAllowLists(left, right []string) []string {
522		switch {
523		case len(left) == 0:
524			return append([]string(nil), right...)
525		case len(right) == 0:
526			return append([]string(nil), left...)
527		}
528		rightSet := make(map[string]struct{}, len(right))
529		for _, value := range right {
530			rightSet[strings.ToLower(strings.TrimSpace(value))] = struct{}{}
531		}
532		result := make([]string, 0, min(len(left), len(right)))
533		seen := make(map[string]struct{})
534		for _, value := range left {
535			key := strings.ToLower(strings.TrimSpace(value))
536			if key == "" {
537				continue
538			}
539			if _, ok := rightSet[key]; !ok {
540				continue
541			}
542			if _, duplicated := seen[key]; duplicated {
543				continue
544			}
545			seen[key] = struct{}{}
546			result = append(result, value)
547		}
548		return result
549	}
550	
551	func unionToolBlockLists(left, right []string) []string {
552		result := make([]string, 0, len(left)+len(right))
553		seen := make(map[string]struct{}, len(left)+len(right))
554		for _, value := range append(append([]string(nil), left...), right...) {
555			key := strings.ToLower(strings.TrimSpace(value))
556			if key == "" {
557				continue
558			}
559			if _, duplicated := seen[key]; duplicated {
560				continue
561			}
562			seen[key] = struct{}{}
563			result = append(result, value)
564		}
565		return result
566	}
567	
568	// convertToSDKTools re-serializes tool params through JSON to ensure they
569	// conform to the OpenAI SDK type.
570	func convertToSDKTools(selected []openai.ChatCompletionToolParam) ([]openai.ChatCompletionToolParam, error) {
571		out := make([]openai.ChatCompletionToolParam, len(selected))
572		for i, tool := range selected {
573			b, err := json.Marshal(tool)
574			if err != nil {
575				return nil, err
576			}
577			if err := json.Unmarshal(b, &out[i]); err != nil {
578				return nil, err
579			}
580		}
581		return out, nil
582	}
583	
584	// filterToolsByDecisionPolicy applies per-decision allow/block lists to the
585	// request tool set. If allowTools is non-empty, only tools whose function name
586	// appears in the allow list are kept. Any tool whose name appears in blockTools
587	// is removed regardless.
588	func filterToolsByDecisionPolicy(tools []openai.ChatCompletionToolParam, allowTools, blockTools []string) []openai.ChatCompletionToolParam {
589		allowSet := make(map[string]bool, len(allowTools))
590		for _, t := range allowTools {
591			allowSet[t] = true
592		}
593		blockSet := make(map[string]bool, len(blockTools))
594		for _, t := range blockTools {
595			blockSet[t] = true
596		}
597		filtered := make([]openai.ChatCompletionToolParam, 0, len(tools))
598		for _, tool := range tools {
599			name := tool.Function.Name
600			if blockSet[name] {
601				continue
602			}
603			if len(allowSet) > 0 && !allowSet[name] {
604				continue
605			}
606			filtered = append(filtered, tool)
607		}
608		return filtered
609	}
610	
611	// updateRequestWithTools updates the request body with the selected tools.
612	func (r *OpenAIRouter) updateRequestWithTools(openAIRequest *openai.ChatCompletionNewParams, response **ext_proc.ProcessingResponse, ctx *RequestContext) error {
613		modifiedBody, err := serializeOpenAIRequestWithStream(openAIRequest, ctx.ExpectStreamingResponse)
614		if err != nil {
615			return err
616		}
617		bodyMutation := &ext_proc.BodyMutation{
618			Mutation: &ext_proc.BodyMutation_Body{
619				Body: modifiedBody,
620			},
621		}
622		commonResponse := ensureRequestBodyCommonResponse(response)
623		commonResponse.Status = ext_proc.CommonResponse_CONTINUE
624		commonResponse.BodyMutation = bodyMutation
625		if commonResponse.HeaderMutation == nil {
626			commonResponse.HeaderMutation = &ext_proc.HeaderMutation{}
627		}
628		ensureHeaderRemoved(commonResponse.HeaderMutation, "content-length")
629		setHeaderValue(commonResponse.HeaderMutation, "content-length", fmt.Sprintf("%d", len(modifiedBody)))
630		if r.shouldClearRouteCache() {
631			commonResponse.ClearRouteCache = true
632			logging.Debugf("Setting ClearRouteCache=true (feature enabled) in updateRequestWithTools")
633		}
634		return nil
635	}
636	
637	func ensureRequestBodyCommonResponse(response **ext_proc.ProcessingResponse) *ext_proc.CommonResponse {
638		if *response == nil {
639			*response = &ext_proc.ProcessingResponse{}
640		}
641		if (*response).GetRequestBody() == nil {
642			(*response).Response = &ext_proc.ProcessingResponse_RequestBody{
643				RequestBody: &ext_proc.BodyResponse{},
644			}
645		}
646		if (*response).GetRequestBody().GetResponse() == nil {
647			(*response).GetRequestBody().Response = &ext_proc.CommonResponse{}
648		}
649		return (*response).GetRequestBody().GetResponse()
650	}
651	
652	func ensureHeaderRemoved(mutation *ext_proc.HeaderMutation, key string) {
653		for _, existing := range mutation.RemoveHeaders {
654			if existing == key {
655				return
656			}
657		}
658		mutation.RemoveHeaders = append(mutation.RemoveHeaders, key)
659	}
660	
661	func clearToolChoiceWhenNoTools(openAIRequest *openai.ChatCompletionNewParams) bool {
662		if openAIRequest == nil || len(openAIRequest.Tools) > 0 || !hasToolChoice(openAIRequest) {
663			return false
664		}
665		logging.Infof("[ToolsPlugin] Clearing tool_choice because no tools are present in the upstream request")
666		openAIRequest.ToolChoice = openai.ChatCompletionToolChoiceOptionUnionParam{}
667		return true
668	}
669	
670	func hasToolChoice(openAIRequest *openai.ChatCompletionNewParams) bool {
671		if openAIRequest == nil {
672			return false
673		}
674		return !param.IsOmitted(openAIRequest.ToolChoice.OfAuto) ||
675			openAIRequest.ToolChoice.OfChatCompletionNamedToolChoice != nil
676	}
677	
678	func setHeaderValue(mutation *ext_proc.HeaderMutation, key, value string) {
679		for _, option := range mutation.SetHeaders {
680			if option.Header != nil && option.Header.Key == key {
681				option.Header.RawValue = []byte(value)
682				option.Header.Value = value
683				return
684			}
685		}
686		mutation.SetHeaders = append(mutation.SetHeaders, &core.HeaderValueOption{
687			Header: &core.HeaderValue{
688				Key:      key,
689				Value:    value,
690				RawValue: []byte(value),
691			},
692		})
693	}
